"""A package generated by the designer must build with colcon and run on a real ROS 2 graph."""

from __future__ import annotations

import os
import shutil
import subprocess
import sys
import time
from pathlib import Path
from typing import Any

import pytest

from ros2inspector.design.codegen import generate_package_result
from ros2inspector.design.models import PackageSpec
from ros2inspector.model.uam import UAM


def _package() -> PackageSpec:
    def node(nid: str, label: str, **groups: Any) -> dict[str, Any]:
        base: dict[str, Any] = {
            "id": nid,
            "label": label,
            "publishers": [],
            "subscribers": [],
            "services": [],
            "clients": [],
            "action_servers": [],
            "action_clients": [],
        }
        base.update(groups)
        return base

    topic = {"name": "/design_chatter", "msgType": "std_msgs/String"}
    return PackageSpec.model_validate(
        {
            "id": "p1",
            "pkg_name": "designed_demo",
            # 'string' is the label most likely to shadow std_msgs.msg.String.
            "nodes": [
                node("n1", "string", publishers=[{"id": "t1", **topic}]),
                node("n2", "listener", subscribers=[{"id": "t2", **topic}]),
            ],
            "edges": [{"id": "e1", "fn": "n1", "ft": "t1", "tn": "n2", "tt": "t2"}],
        }
    )


@pytest.mark.requires_ros2
def test_generated_nodes_join_the_live_graph(tmp_path: Path) -> None:
    rclpy = pytest.importorskip("rclpy")
    ws = tmp_path / "ws"
    generate_package_result(_package(), ws / "src")
    module_dir = ws / "src" / "designed_demo" / "designed_demo"

    static_topic = next(
        topic
        for topic in UAM.build(ws, use_cache=False).topics()
        if topic["name"] == "/design_chatter"
    )
    assert static_topic["msg_type"] == "std_msgs/String"

    processes = [
        subprocess.Popen([sys.executable, str(module_dir / f"{name}.py")], env=dict(os.environ))
        for name in ("string", "listener")
    ]
    observer = None
    try:
        rclpy.init()
        observer = rclpy.create_node("ros2inspector_design_observer")
        deadline = time.monotonic() + 20.0
        names: set[str] = set()
        publishers: list[Any] = []
        subscribers: list[Any] = []
        while time.monotonic() < deadline:
            rclpy.spin_once(observer, timeout_sec=0.2)
            names = {name for name, _ in observer.get_node_names_and_namespaces()}
            publishers = observer.get_publishers_info_by_topic("/design_chatter")
            subscribers = observer.get_subscriptions_info_by_topic("/design_chatter")
            if {"string", "listener"} <= names and publishers and subscribers:
                break
        assert {"string", "listener"} <= names
        assert {info.topic_type for info in publishers} == {"std_msgs/msg/String"}
        assert {info.topic_type for info in subscribers} == {"std_msgs/msg/String"}
        assert all(process.poll() is None for process in processes), "a generated node crashed"
    finally:
        if observer is not None:
            observer.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()
        for process in processes:
            process.terminate()
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait(timeout=5)


@pytest.mark.requires_ros2
def test_generated_package_builds_with_colcon(tmp_path: Path) -> None:
    colcon = shutil.which("colcon")
    if colcon is None:
        pytest.skip("colcon is not installed")
    ws = tmp_path / "ws"
    generate_package_result(_package(), ws / "src")
    result = subprocess.run(
        [colcon, "build", "--base-paths", "src", "--event-handlers", "console_direct+"],
        cwd=ws,
        capture_output=True,
        text=True,
        timeout=600,
    )
    assert result.returncode == 0, result.stdout + result.stderr
    install = ws / "install" / "designed_demo"
    for executable in ("string", "listener"):
        assert (install / "lib" / "designed_demo" / executable).is_file()
    assert (install / "share" / "designed_demo" / "launch" / "launch.py").is_file()
    assert (install / "share" / "designed_demo" / "package.xml").is_file()
    index = install / "share" / "ament_index" / "resource_index" / "packages" / "designed_demo"
    assert index.is_file()
